import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-score',
  template: '<button (click)="add()">Score: {{ score() }}</button>',
})
export class Score {
  score = signal(0);

  add(): void {
    this.score.update(value => value + 1);
  }
}
